package erratum

// Use opens a resource via the provided opener, frobs it with the given
// input, and closes the resource exactly once in all cases.
//
// If the opener fails with a TransientError, it keeps retrying. Any other
// error from the opener is returned as-is. If Frob panics, the panic is
// recovered: if it is a FrobError, Defrob is called with the error's
// defrobTag (before Close), and the error is returned from Use.
func Use(opener ResourceOpener, input string) error {
	var r Resource
	var err error
	for {
		r, err = opener()
		if err == nil {
			break
		}
		if _, ok := err.(TransientError); !ok {
			return err
		}
	}

	defer func() {
		if p := recover(); p != nil {
			if fe, ok := p.(FrobError); ok {
				r.Defrob(fe.defrobTag)
			}
			r.Close()
			if e, ok := p.(error); ok {
				err = e
			} else {
				panic(p)
			}
		}
	}()

	r.Frob(input)
	r.Close()
	return nil
}

